Translate("frFR", "orgrimmar", {
	title = "Orgrimmar",
	sections = {
		{
			title = "Résumé",
			text = [=[Orgrimmar est la capitale de la {link:horde}Horde{/link}, une cité-forteresse dans les montagnes du nord de {link:durotar}Durotar{/link}. Ses murs sont de bois, de pierre et de fer, et une grande partie en est taillée dans la roche rouge des canyons. Par sa grande porte passent des guerriers orcs, des chasseurs trolls, des anciens taurens et les pâles émissaires des {link:forsaken}Réprouvés{/link}. En son cœur se dresse la salle du chef de guerre. La cité porte le nom d'{link:orgrim-doomhammer}Orgrim Doomhammer{/link}, qui mourut pour que son peuple soit libre, et elle doit montrer au monde ce que sont devenus les orcs : non plus une machine de guerre au service des démons, mais une nation.]=],
		},
		{
			title = "Origines",
			text = [=[Quand la guerre contre la {link:burning-legion}Légion ardente{/link} fut gagnée, {link:thrall}Thrall{/link} mena son peuple sur la côte est de {link:kalimdor}Kalimdor{/link} et entreprit de lui bâtir un foyer. Il choisit un site où les montagnes du nord garderaient les arrières de la cité, et il la nomma d'après Doomhammer, son ami et son maître. Les orcs ne l'élevèrent pas seuls. Les {link:tauren}taurens{/link}, les {link:darkspear-trolls}Darkspear{/link} et les gobelins prêtèrent la main, et la cité s'éleva vite, vallée après vallée. Alors même qu'on la bâtissait, les humains de {link:kul-tiras}Kul Tiras{/link} vinrent l'abattre. Ils échouèrent, et Orgrimmar tint bon.]=],
		},
		{
			title = "Le temps présent",
			text = [=[Orgrimmar est la plus grande cité de la {link:horde}Horde{/link}, et son cœur. {link:thrall}Thrall{/link} règne depuis {link:grommash-hold}Grommash Hold{/link}, avec le chef des {link:darkspear-trolls}Darkspear{/link} et ses vieux conseillers à ses côtés. Ses marchés sont bruyants, ses salles d'entraînement sont pleines, et ses jeunes guerriers ont faim de leur première bataille. Mais la cité a des ennemis dans ses murs. Les cultistes de la {link:burning-blade}Lame ardente{/link} murmurent dans le {link:cleft-of-shadow}Cleft of Shadow{/link}, et sous la cité, dans les grottes brûlantes du {link:ragefire-chasm}Gouffre de Ragefeu{/link}, une secte du {link:shadow-council}Conseil des ombres{/link} rassemble ses forces. Thrall en sait plus sur eux qu'ils ne le croient.]=],
		},
		{
			title = "Habitants",
			text = [=[• {b}Les orcs.{/b} Guerriers, chamans, forgerons et marchands, libérés de la malédiction du démon et fiers de l'être.
• {b}Les trolls {link:darkspear-trolls}Darkspear{/link}.{/b} Ils ont leur propre quartier dans le {link:valley-of-spirits}Valley of Spirits{/link}.
• {b}Les taurens.{/b} Des anciens et des voyageurs de {link:thunder-bluff}Thunder Bluff{/link}, alliés du chef de guerre.
• {b}Les {link:forsaken}Réprouvés{/link}.{/b} Des émissaires de {link:sylvanas-windrunner}Sylvanas Windrunner{/link}, nouvellement acceptés dans la {link:horde}Horde{/link} et observés avec un certain malaise.
• {b}Les gobelins.{/b} Marchands et ingénieurs qui servent quiconque paie.
• {b}La {link:burning-blade}Lame ardente{/link}.{/b} Cachée parmi les autres, comme la pourriture se cache dans une poutre saine.]=],
		},
		{
			title = "Histoire",
			text = [=[• {b}La fondation.{/b} La cité fut élevée après la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, tandis que les orcs domptaient les terres alentour et chassaient huranes, centaures et harpies.
• {b}La guerre de l'amiral.{/b} La flotte de {link:daelin-proudmoore}Daelin Proudmoore{/link} menaça la jeune cité depuis la mer. La {link:horde}Horde{/link} brisa le fort de l'amiral et le tua à {link:theramore-isle}Theramore{/link}.
• {b}Le temps présent.{/b} La Horde s'est agrandie jusqu'à inclure les {link:forsaken}Réprouvés{/link} de {link:lordaeron}Lordaeron{/link}, et Orgrimmar est devenue le lieu de rencontre de tous ses peuples.]=],
		},
		{
			title = "Récits de la cité",
			text = [=[• La forteresse du chef de guerre s'appelle {link:grommash-hold}Grommash Hold{/link}, d'après {link:grom-hellscream}Grom Hellscream{/link}, qui tua le démon {link:mannoroth}Mannoroth{/link} et libéra les orcs de la malédiction du sang.
• Quand un héros de la {link:horde}Horde{/link} rapporte la tête d'un grand ennemi, on la dresse dans le {link:valley-of-strength}Valley of Strength{/link} pour que toute la cité la voie.
• Dans la taverne du Valley of Strength boit un {link:tauren}tauren{/link} nommé {link:gamon}Gamon{/link}. Il sert un troll qui commerce avec les pirates de la côte sud, et il est rarement sobre.
• Les voleurs de la cité disent qu'une société appelée la Shattered Hand œuvre dans l'ombre du Cleft, et qu'elle juge le chef de guerre trop prudent.]=],
		},
	},
})

Translate("frFR", "valley-of-strength", {
	title = "Valley of Strength",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Valley of Strength se trouve juste derrière la grande porte d'{link:orgrimmar}Orgrimmar{/link}. C'est le lieu le plus animé de la cité. On y trouve la banque, l'hôtel des ventes et la taverne, et au-dessus la tour où se posent les coursiers du vent. Des grunts surveillent chaque chemin. Des voyageurs de tous les peuples de la {link:horde}Horde{/link} se pressent dans ses allées, et les nouvelles de tout {link:kalimdor}Kalimdor{/link} y passent. C'est ici aussi que la Horde célèbre ses victoires. Les têtes des ennemis abattus sont dressées au-dessus de la vallée, et les seigneurs de la cité appellent le peuple à honorer les héros qui les ont prises.]=],
		},
	},
})

Translate("frFR", "the-drag", {
	title = "The Drag",
	aliases = { "Drag" },
	sections = {
		{
			title = "Résumé",
			text = [=[The Drag est une longue rue ombragée qui serpente depuis le {link:valley-of-strength}Valley of Strength{/link} vers les profondeurs de la cité. Ses murs sont bordés de boutiques. Travailleurs du cuir, tailleurs, alchimistes et ingénieurs travaillent dans ses échoppes, et la fumée des feux de cuisine flotte entre les auvents. C'est un lieu bondé et bruyant, et tous les marchands n'y sont pas honnêtes. Ceux qui cherchent un métier viennent ici l'apprendre. Depuis The Drag, des chemins mènent au {link:valley-of-honor}Valley of Honor{/link} et descendent dans le {link:cleft-of-shadow}Cleft of Shadow{/link}.]=],
		},
	},
})

Translate("frFR", "cleft-of-shadow", {
	title = "Cleft of Shadow",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Cleft of Shadow est une gorge sombre au cœur d'{link:orgrimmar}Orgrimmar{/link}, où le soleil pénètre rarement. C'est le quartier des voleurs, des démonistes et des empoisonneurs. Le démoniste {link:neeru-fireblade}Neeru Fireblade{/link} y a sa tente, et c'est ici que la Shattered Hand se réunit en secret. Au fond de la faille, un passage descend jusqu'au {link:ragefire-chasm}Gouffre de Ragefeu{/link}. Les honnêtes gens de la cité évitent le Cleft, et ceux qui y vivent le préfèrent ainsi. Bien des secrets du chef de guerre sont gardés ici, et ceux de certains de ses ennemis aussi.]=],
		},
	},
})

Translate("frFR", "valley-of-honor", {
	title = "Valley of Honor",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Valley of Honor se trouve au nord-est d'{link:orgrimmar}Orgrimmar{/link} et appartient aux guerriers de la {link:horde}Horde{/link}. Dans le Hall of the Brave, de vieux vétérans enseignent aux jeunes l'art de la hache et du bouclier. Les chasseurs y ont leurs pavillons, et les forges des forgerons de la cité brûlent jour et nuit. La vallée résonne du tintement des marteaux et des cris de ceux qui s'entraînent. Un {link:orcs}orc{/link} qui veut être reconnu comme guerrier vient ici le prouver.]=],
		},
	},
})

Translate("frFR", "valley-of-spirits", {
	title = "Valley of Spirits",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Valley of Spirits s'étend le long du sud-ouest d'{link:orgrimmar}Orgrimmar{/link}. C'est le quartier des {link:darkspear-trolls}Darkspear{/link}. Leurs huttes se dressent parmi les bâtiments orcs, et leurs féticheurs, leurs prêtres et leurs mages y pratiquent les vieilles coutumes de la tribu. C'est dans cette vallée que les jeunes prêtres trolls sont admis dans le cercle de leurs anciens. Son bassin immobile reflète les murs rouges qui le surplombent. De toutes les vallées de la cité, c'est la plus paisible, et les trolls la gardent ainsi. Ici, les Darkspear se souviennent des îles qu'ils ont perdues.]=],
		},
	},
})

Translate("frFR", "valley-of-wisdom", {
	title = "Valley of Wisdom",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Valley of Wisdom se trouve au nord-ouest d'{link:orgrimmar}Orgrimmar{/link}, loin du bruit de la porte. C'est le siège du chef de guerre. À son extrémité s'élève {link:grommash-hold}Grommash Hold{/link}, et autour se rassemblent les chamans de la {link:horde}Horde{/link}, qui enseignent aux jeunes à parler aux {link:elements}éléments{/link} comme le faisaient leurs ancêtres sur Draenor. Les anciens de la cité viennent ici donner et recevoir conseil. C'est un lieu de savoir, et de pouvoir. Beaucoup de ceux qui recherchent la faveur du chef de guerre empruntent sa route.]=],
		},
	},
})

Translate("frFR", "grommash-hold", {
	title = "Grommash Hold",
	sections = {
		{
			title = "Résumé",
			text = [=[Grommash Hold est la forteresse du chef de guerre, bâtie dans les falaises du {link:valley-of-wisdom}Valley of Wisdom{/link}. Elle porte le nom de {link:grom-hellscream}Grom Hellscream{/link}, dont le sacrifice libéra les orcs du sang du démon. Sa salle est vaste et sombre, éclairée par le feu. À son extrémité, {link:thrall}Thrall{/link} tient sa cour depuis son trône. {link:vol-jin}Vol'jin{/link} des {link:darkspear-trolls}Darkspear{/link} se tient à ses côtés, avec le vieux guerrier {link:eitrigg}Eitrigg{/link} et le grand prophète {link:zor-lonetree}Zor Lonetree{/link}. Les gardes d'élite kor'kron gardent ses portes, et nul ne se présente devant le chef de guerre sans leur permission.]=],
		},
	},
})

Translate("frFR", "thrall", {
	title = "Thrall",
	subtitle = "Chef de guerre de la Horde",
	found = "Grommash Hold, dans le Valley of Wisdom",
	hint = [=[Sollicitez une audience auprès du chef de guerre à Grommash Hold.]=],
	allegiance = "Horde · Clan Frostwolf",
	aliases = { "Chef de guerre Thrall" },
	sections = {
		{
			title = "Résumé",
			text = [=[Thrall est le chef de guerre de la {link:horde}Horde{/link}. Il naquit fils de Durotan, chef du {link:frostwolf-clan}clan Frostwolf{/link}, et fut élevé en esclave parmi les humains. Il brisa ses chaînes, libéra son peuple des camps d'internement et le ramena aux anciennes voies des chamans. Il le mena par-delà la mer jusqu'à {link:kalimdor}Kalimdor{/link} et lui donna une patrie. Même ses ennemis lui reconnaissent de l'honneur.]=],
		},
		{
			title = "Importance",
			text = [=[Thrall fit une nouvelle {link:horde}Horde{/link} des cendres de l'ancienne. Sous sa conduite, les {link:orcs}orcs{/link} ne sont plus les serviteurs des démons, et la Horde n'est plus seulement une horde d'orcs.]=],
		},
		{
			title = "L'esclave",
			text = [=[Durotan et sa compagne, Draka, furent assassinés dans les terres sauvages quand leur fils était nourrisson. Un officier humain nommé {link:aedelas-blackmoore}Aedelas Blackmoore{/link} trouva l'enfant et l'emmena au {link:durnholde-keep}Donjon de Durnholde{/link}. Il le nomma Thrall, un mot qui désigne un esclave, et l'éleva pour combattre dans {link:gurubashi-arena}l'arène{/link} et peut-être un jour mener une armée pour lui. Une jeune humaine, {link:taretha-foxton}Taretha Foxton{/link}, lui montra de la bonté, et avec son aide il s'évada.]=],
		},
		{
			title = "Le libérateur",
			text = [=[Dans les terres sauvages, Thrall trouva {link:grom-hellscream}Grom Hellscream{/link} et les derniers clans libres. Parmi les {link:frostwolf-clan}Frostwolf{/link}, dans les {link:alterac-mountains}Montagnes d'Alterac{/link}, le vieux chaman {link:drek-thar}Drek'Thar{/link} lui apprit à parler aux {link:elements}éléments{/link}. Puis il rencontra {link:orgrim-doomhammer}Orgrim Doomhammer{/link}, et ensemble ils frappèrent les camps d'internement. Doomhammer tomba au combat, et avant de mourir il donna à Thrall son marteau, son armure et son titre. Thrall libéra les orcs et brisa la puissance de {link:aedelas-blackmoore}Blackmoore{/link} à {link:durnholde-keep}Durnholde{/link}.]=],
		},
		{
			title = "L'exode",
			text = [=[Un prophète vint à Thrall en songe et lui dit de mener son peuple vers l'ouest. Il le fit. Une tempête jeta sa flotte sur les îles des {link:darkspear-trolls}Darkspear{/link}, et il sauva les trolls de leurs ennemis. En {link:kalimdor}Kalimdor{/link}, il gagna l'amitié de {link:cairne-bloodhoof}Cairne Bloodhoof{/link} et des taurens. Il vit Grom retomber sous l'emprise du sang du démon, le libéra, et le regarda mourir en tuant {link:mannoroth}Mannoroth{/link}. Lors de la {link:battle-of-mount-hyjal}bataille du mont Hyjal{/link}, il combattit aux côtés des humains et des elfes de la nuit contre {link:archimonde}Archimonde{/link}. Ensuite, il fonda {link:durotar}Durotar{/link} et {link:orgrimmar}Orgrimmar{/link}, et il fit la paix avec {link:jaina-proudmoore}Jaina Proudmoore{/link} de {link:theramore-isle}Theramore{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il libéra les orcs des camps d'internement.
• Il mena la {link:horde}Horde{/link} en {link:kalimdor}Kalimdor{/link} et fonda la nation de {link:durotar}Durotar{/link}.
• Il forgea des alliances avec les {link:darkspear-trolls}Darkspear{/link}, les taurens et les {link:forsaken}Réprouvés{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Ennemis cachés",
			hint = [=[Apportez au chef de guerre une preuve venue du Rocher du crâne.]=],
			text = [=[Thrall ne tolère pas les traîtres, mais il ne les frappe pas trop tôt. Un coup porté trop tôt ne ferait qu'enfoncer la pourriture plus profondément. Il lui fallait quelqu'un de jeune et d'inconnu, capable d'aller là où ses propres agents ne pouvaient aller. L'insigne d'un lieutenant de la {link:burning-blade}Lame ardente{/link}, pris au {link:skull-rock}Rocher du crâne{/link}, était la clé de la porte de l'ennemi.]=],
		},
		{
			title = "Le démoniste du Cleft",
			hint = "Portez l'insigne au démoniste du Cleft of Shadow.",
			text = [=[Thrall révéla ce que peu de gens à {link:orgrimmar}Orgrimmar{/link} savaient. Le démoniste {link:neeru-fireblade}Neeru Fireblade{/link}, qui prétend chasser les démons, est le véritable chef de la {link:burning-blade}Lame ardente{/link}. Thrall le sait depuis longtemps, et il laisse Neeru croire qu'on lui fait confiance. Le démoniste est plus utile libre que mort, car c'est par lui que Thrall compte trouver {link:shadow-council}le Conseil{/link} des ombres et le détruire enfin.]=],
		},
		{
			title = "La Searing Blade",
			hint = [=[Abattez les chefs de la Searing Blade dans le Gouffre de Ragefeu.]=],
			text = [=[Sous la cité, une secte appelée la Searing Blade répondait à {link:neeru-fireblade}Neeru{/link}. Ses véritables maîtres étaient un {link:satyrs}satyre{/link}, {link:bazzalan}Bazzalan{/link}, et un démoniste, {link:jergosh-the-invoker}Jergosh{/link}. Sur ordre de Thrall, tous deux furent tués, et nul ne put dire que c'était de son fait. Neeru enragea, et dans sa colère il révéla à son faux lieutenant de nouveaux projets en {link:ashenvale}Orneval{/link} et dans les {link:the-barrens}Tarides{/link}.]=],
		},
		{
			title = "Rend est vivant",
			hint = [=[Apprenez ce que le chef de guerre voulait faire des Blackrock.]=],
			text = [=[La nouvelle arriva que Rend Blackhand, longtemps cru mort, avait levé sa propre {link:horde}Horde{/link} au Pic {link:blackrock-mountain}Blackrock{/link} et s'était proclamé chef de guerre. Thrall frappa du poing sur son trône. Il demanda la tête de Rend, et quand elle lui parvint, il honora celui qui l'avait apportée.]=],
		},
	},
	mentions = {
		{ text = "Ennemis cachés, l'insigne" },
		{ text = "Ennemis cachés, le démoniste" },
		{ text = "Ennemis cachés, la Searing Blade" },
		{ text = "Ennemis cachés, le dernier rapport" },
		{ text = "La sagesse d'{link:eitrigg}Eitrigg{/link}" },
		{ text = "Pour la {link:horde}Horde{/link} !" },
		{ text = "Le sauvetage royal" },
		{ text = "La princesse sauvée ?" },
		{ text = "La négociation de la paix" },
		{ text = "Victoire pour la {link:horde}Horde{/link}" },
		{ text = "Le seigneur des {link:blackrock-mountain}Blackrock{/link}" },
	},
	bonds = {
		{ id = "vol-jin", name = "Vol'jin", note = "son conseiller et allié" },
		{ id = "eitrigg", name = "Eitrigg", note = "son vieux conseiller" },
		{ id = "neeru-fireblade", name = "Neeru Fireblade", note = "le traître qu'il surveille" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "son ami et mentor" },
		{ id = "grom-hellscream", name = "Grom Hellscream", note = "son ami, tombé" },
		{ id = "cairne-bloodhoof", name = "Cairne Bloodhoof", note = "son allié" },
		{ id = "jaina-proudmoore", name = "Jaina Proudmoore", note = "son alliée dans la paix" },
	},
})

Translate("frFR", "vol-jin", {
	title = "Vol'jin",
	subtitle = "Chef des Darkspear",
	found = "Grommash Hold, aux côtés du chef de guerre",
	hint = [=[Parlez au troll qui se tient aux côtés du chef de guerre à Grommash Hold.]=],
	allegiance = "Horde · Trolls Darkspear",
	sections = {
		{
			title = "Résumé",
			text = [=[Vol'jin est le chef des {link:darkspear-trolls}Darkspear{/link} et un chasseur des ombres d'une grande habileté. Il est le fils de Sen'jin, qui donna sa vie pour que la tribu puisse suivre les orcs vers un nouveau monde. Vol'jin tient le serment de son père. Il se tient aux côtés de {link:thrall}Thrall{/link} à {link:grommash-hold}Grommash Hold{/link}, conseillant le chef de guerre et parlant pour son peuple, tandis que les Darkspear attendent dans leur village au bord de la mer le jour où ils pourront reprendre leurs îles.]=],
		},
		{
			title = "Importance",
			text = [=[Par Vol'jin, les {link:trolls}trolls{/link} sont devenus un véritable peuple de la {link:horde}Horde{/link} et non plus seulement ses alliés. Il est la preuve que la Horde de {link:thrall}Thrall{/link} est une ligue de peuples libres.]=],
		},
		{
			title = "Le serment de Sen'jin",
			text = [=[Les {link:darkspear-trolls}Darkspear{/link} étaient des parias, chassés des jungles et dispersés à travers les îles des mers du sud. Quand une tempête jeta la flotte de {link:thrall}Thrall{/link} sur leurs rivages, la tribu luttait pour sa survie contre les humains et les murlocs des profondeurs. Thrall combattit aux côtés des trolls. Leur chef, Sen'jin, fut pris par les murlocs et ne revint pas, mais il avait prévu que le chef de guerre {link:orcs}orc{/link} mènerait son peuple vers un nouveau foyer. Le fils de Sen'jin engagea la tribu envers la {link:horde}Horde{/link}.]=],
		},
		{
			title = "Les îles et le traître",
			text = [=[Après la guerre contre la Légion, les {link:darkspear-trolls}Darkspear{/link} s'établirent sur les {link:echo-isles}Îles de l'Écho{/link}, au large de la côte de {link:durotar}Durotar{/link}. Leur paix fut brève. La flotte de {link:kul-tiras}Kul Tiras{/link} fondit sur les îles, et Vol'jin dut veiller à l'évacuation de son peuple tandis que la {link:horde}Horde{/link} contre-attaquait les navires humains. Puis vint un coup pire encore : {link:zalazane}Zalazane{/link}, un féticheur de leur propre tribu, retourna sa magie contre eux. Les Darkspear libres s'enfuirent sur le continent et y bâtirent un village, qu'ils nommèrent d'après Sen'jin.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il engagea les {link:darkspear-trolls}Darkspear{/link} envers la {link:horde}Horde{/link} après la mort de son père.
• Il mena son peuple en {link:kalimdor}Kalimdor{/link} et l'établit sur les {link:echo-isles}Îles de l'Écho{/link}.
• Il conseille le chef de guerre à {link:grommash-hold}Grommash Hold{/link}.
• Il avertit {link:thrall}Thrall{/link}, encore et encore, de ne pas se fier aux humains.]=],
		},
		{
			title = "Non consigné",
			text = [=[Peu de choses sont écrites ici sur la jeunesse de Vol'jin. Cette entrée ne rapporte que ce que révèlent les histoires et ses actes.]=],
		},
	},
	chapters = {
		{
			title = "Les ordres de l'amiral",
			hint = "Portez à Orgrimmar les ordres de l'amiral mort.",
			text = [=[Quand les ordres de {link:daelin-proudmoore}Daelin Proudmoore{/link} furent trouvés au {link:tiragarde-keep}Donjon de Tiragarde{/link}, ils parvinrent enfin à Vol'jin, à {link:grommash-hold}Grommash Hold{/link}. Il les lut et n'en fut pas surpris. Il avait longtemps pressé le chef de guerre de ne pas se fier aux humains, et les plans de l'amiral lui donnaient raison. Il ne s'en vanta pas. Il alla aussitôt conseiller {link:thrall}Thrall{/link}.]=],
		},
		{
			title = "Le maître des maléfices",
			hint = "Abattez le féticheur qui tient les Îles de l'Écho.",
			text = [=[La nouvelle de la chute de {link:zalazane}Zalazane{/link} parvint à {link:orgrimmar}Orgrimmar{/link} depuis le {link:sen-jin-village}Village de Sen'jin{/link}. Pour le chef des {link:darkspear-trolls}Darkspear{/link}, ce fut un maigre réconfort. La malédiction du traître pèse encore sur les îles, et beaucoup du peuple de Vol'jin y errent encore, l'esprit vide. Le jour du retour de la tribu n'est pas encore venu.]=],
		},
	},
	mentions = {
		{ text = "Les ordres de l'amiral" },
		{
			text = [=[{link:zalazane}Zalazane{/link}, tué à la demande de maître Gadrin]=],
		},
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "son chef de guerre" },
		{ id = "zalazane", name = "Zalazane", note = "le traître de sa tribu" },
		{ id = "master-gadrin", name = "Maître Gadrin", note = "ancien de son peuple" },
		{ id = "eitrigg", name = "Eitrigg", note = "un autre conseiller" },
	},
})

Translate("frFR", "eitrigg", {
	title = "Eitrigg",
	subtitle = "Conseiller du chef de guerre",
	found = "Grommash Hold",
	hint = [=[Parlez au vieux guerrier qui conseille le chef de guerre à Grommash Hold.]=],
	allegiance = "Horde · Clan Blackrock (autrefois)",
	sections = {
		{
			title = "Résumé",
			text = [=[Eitrigg est un vieux guerrier {link:orcs}orc{/link} du {link:blackrock-clan}clan Blackrock{/link} qui sert {link:thrall}Thrall{/link} comme conseiller et comme superviseur des recrues de la {link:horde}Horde{/link}. Il combattit dans les guerres de l'ancienne Horde sous Blackhand et Doomhammer. Il en vint à haïr les adorateurs de démons qui égarèrent son peuple, et pendant un temps il quitta complètement la Horde. Il revint quand il entendit la vision de Thrall d'une Horde guidée par des chamans plutôt que par des démons.]=],
		},
		{
			title = "Importance",
			text = [=[Eitrigg est un pont entre l'ancienne {link:horde}Horde{/link} et la nouvelle. Il connaît les coutumes des {link:blackrock-mountain}Blackrock{/link} mieux que tout {link:orcs}orc{/link} d'{link:orgrimmar}Orgrimmar{/link}, et il sait ce qu'il en coûte de les quitter.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il servit comme lieutenant du chef de guerre des {link:blackrock-mountain}Blackrock{/link} aux jours d'avant la {link:dark-portal}Porte des Ténèbres{/link}, aux côtés d'{link:orgrim-doomhammer}Orgrim Doomhammer{/link}.
• Il surveilla l'assassin {link:garona}Garona{/link} durant la {link:second-war}Deuxième Guerre{/link}, et il la laissa partir quand elle s'enfuit.
• Il quitta la {link:horde}Horde{/link} et erra au nord dans les terres des humains, où il fut fait prisonnier et sauvé par le chef de guerre.
• Il supervise l'entraînement des nouvelles recrues pour {link:thrall}Thrall{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Rend est vivant",
			hint = "Apportez à Eitrigg des nouvelles des Blackrock.",
			text = [=[La nouvelle vint des {link:badlands}Terres ingrates{/link} : Rend Blackhand, fils de l'ancien chef de guerre Blackhand, était vivant et rassemblait le {link:blackrock-clan}clan Blackrock{/link} au Pic {link:blackrock-mountain}Blackrock{/link}. On croyait Rend tué depuis longtemps. Personne à {link:orgrimmar}Orgrimmar{/link} ne connaissait les Blackrock comme Eitrigg, et personne n'avait de meilleur titre à la vengeance. Il fit suivre la nouvelle à {link:thrall}Thrall{/link}.]=],
		},
		{
			title = "La tête de Rend",
			hint = "Apportez la tête de Rend Blackhand au chef de guerre.",
			text = [=[Quand la tête de Rend fut déposée devant le chef de guerre, Eitrigg vit se briser la dernière ombre du clan qu'il avait jadis servi. Les {link:blackrock-mountain}Blackrock{/link} furent de nouveau plongés dans le chaos. Pour le vieux guerrier, c'était une dette réglée.]=],
		},
	},
	mentions = {
		{ text = "La nouvelle {link:horde}Horde{/link}" },
		{ text = "La sagesse d'Eitrigg" },
		{ text = "Pour la {link:horde}Horde{/link} !" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "son chef de guerre et sauveur" },
		{ id = "orgrim-doomhammer", name = "Orgrim Doomhammer", note = "son vieux camarade" },
		{ id = "vol-jin", name = "Vol'jin", note = "un autre conseiller" },
		{ id = "tirion-fordring", name = "Tirion Fordring", note = "l'humain qui le sauva" },
	},
})

Translate("frFR", "neeru-fireblade", {
	title = "Neeru Fireblade",
	subtitle = "Démoniste du Cleft of Shadow",
	found = "Sa tente dans le Cleft of Shadow",
	hint = [=[Cherchez le démoniste dont la tente se dresse dans le Cleft of Shadow.]=],
	allegiance = "Horde (prétendue)",
	aliases = { "Neeru" },
	sections = {
		{
			title = "Résumé",
			text = [=[Neeru Fireblade est un démoniste qui vit dans le {link:cleft-of-shadow}Cleft of Shadow{/link}. Peu d'orcs font confiance à ses semblables, car ce sont des démonistes qui lièrent les premiers les orcs aux démons. Neeru prétend n'user de ses arts que contre les démons. Depuis la dernière guerre, dit-il, il traque toute trace de corruption démoniaque dans la société orque, et il sert le chef de guerre en extirpant les cultes qui se cachent dans sa cité.]=],
		},
		{
			title = "Importance",
			text = [=[Neeru se tient au centre de la lutte contre la {link:burning-blade}Lame ardente{/link}. Chaque fil du culte en {link:durotar}Durotar{/link} semble ramener au {link:cleft-of-shadow}Cleft of Shadow{/link}.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il étudie les colliers brûlants de la {link:burning-blade}Lame ardente{/link}.
• Il ordonne la destruction de la Graine démoniaque, un objet de puissance démoniaque, sur le {link:dreadmist-peak}Pic de Brume-funeste{/link} dans les {link:the-barrens}Tarides{/link}.
• Il envoie des héros dans le {link:ragefire-chasm}Gouffre de Ragefeu{/link} tuer le gangregarde {link:taragaman-the-hungerer}Taragaman{/link}.
• Il échange des herbes avec le féticheur {link:witch-doctor-uzer-i}Uzer'i{/link} de {link:feralas}Féralas{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Le collier brûlant",
			hint = [=[Apportez au Cleft of Shadow un collier brûlant de la part de Margoz.]=],
			text = [=[Quand {link:margoz}Margoz{/link} lui envoya un collier brûlant, Neeru l'examina de près. Il nomma le culte qui l'avait fabriqué, la {link:burning-blade}Lame ardente{/link}, et l'objet de puissance autour duquel il se rallie : la Graine démoniaque. Il voulait qu'elle soit détruite.]=],
		},
		{
			title = "La Graine démoniaque",
			hint = [=[Détruisez la Graine démoniaque au sommet du Pic de Brume-funeste.]=],
			text = [=[L'assistant de Neeru, Ak'Zeloth, prépara des pierres pour briser le lien de la Graine avec la Légion. Quand la Graine fut détruite, des vagues de puissance traversèrent l'éther. Ak'Zeloth les sentit, et il avertit que d'autres les avaient senties aussi.]=],
		},
		{
			title = "Loyautés véritables",
			hint = "Apprenez ce que le chef de guerre sait de Neeru.",
			text = [=[Neeru est le chef secret de la {link:burning-blade}Lame ardente{/link} et un serviteur du {link:shadow-council}Conseil des ombres{/link}. Il croit {link:thrall}Thrall{/link} assez sot pour lui faire confiance. Il se trompe : le chef de guerre sait, et le laisse vivre parce qu'il est utile. Neeru envoie les fidèles de Thrall mourir dans le {link:ragefire-chasm}Gouffre de Ragefeu{/link}, et met à l'épreuve la Searing Blade pour voir lesquels de ses membres sont dignes. Quand un jeune lieutenant de la Lame vint à lui porteur du bon insigne, Neeru accueillit un espion.]=],
		},
		{
			title = "L'Affamé",
			hint = "Tuez le gangregarde qui mène la Searing Blade.",
			text = [=[Neeru désigna le gangregarde {link:taragaman-the-hungerer}Taragaman l'Affamé{/link} comme le maître de la Searing Blade et demanda son cœur, pour plaire au chef de guerre. La Searing Blade lui était sacrifiable. Seuls deux de ses chefs comptaient, et ce n'était pas le gangregarde.]=],
		},
	},
	mentions = {
		{ text = "Neeru Fireblade" },
		{ text = "Ombres ardentes" },
		{ text = "Ak'Zeloth" },
		{ text = "La Graine démoniaque" },
		{ text = "Ennemis cachés" },
		{ text = "Tuer la bête" },
		{ text = "Une étrange requête" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "le chef de guerre qui le surveille" },
		{ id = "margoz", name = "Margoz", note = "lui envoya un collier" },
		{ id = "gazz-uz", name = "Gazz'uz", note = "un serviteur de la Lame" },
		{ id = "taragaman-the-hungerer", name = "Taragaman l'Affamé", note = "le gangregarde qu'il sacrifia" },
	},
})

Translate("frFR", "zor-lonetree", {
