			text = [=[Les esprits des {link:stonetalon-mountains}Serres-Rocheuses{/link}]=],
		},
		{ text = "Au rapport auprès de Zor" },
		{ text = "Au service de la {link:horde}Horde{/link}" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "son chef de guerre" },
	},
})

Translate("frFR", "overlord-runthak", {
