	hint = [=[Parlez au suzerain qui monte la garde dans le Valley of Strength.]=],
	allegiance = "Horde",
	aliases = { "Runthak" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le suzerain Runthak exécute les ordres du chef de guerre sans poser de questions. Il le dit lui-même, et il en est fier. Il maintient l'ordre dans le {link:valley-of-strength}Valley of Strength{/link} et surveille ses foules. Quand un héros de la {link:horde}Horde{/link} revient avec la tête d'un grand ennemi, c'est Runthak qui appelle la cité à la voir.]=],
		},
		{
			title = "Importance",
			text = [=[Runthak est la voix des triomphes de la {link:horde}Horde{/link}. Par lui, le peuple d'{link:orgrimmar}Orgrimmar{/link} apprend les noms de ceux qui combattent pour lui.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il dresse les trophées des victoires de la {link:horde}Horde{/link} au-dessus du {link:valley-of-strength}Valley of Strength{/link}.
• Il récompense les héros que le chef de guerre lui envoie.]=],
		},
	},
	mentions = {
		{ text = "À la vue de tous" },
		{ text = "Le voyage ne fait que commencer" },
	},
	bonds = {
		{ id = "thrall", name = "Thrall", note = "son chef de guerre" },
	},
})

Translate("frFR", "gamon", {
	title = "Gamon",
	subtitle = "Habitué de la taverne",
	found = "La taverne du Valley of Strength",
	hint = [=[Trouvez le tauren qui boit dans la taverne du Valley of Strength.]=],
	allegiance = "Aucune",
	sections = {
		{
			title = "Résumé",
			text = [=[Gamon est un grand {link:tauren}tauren{/link} qu'on trouve d'ordinaire dans la taverne du {link:valley-of-strength}Valley of Strength{/link}, et rarement sobre. Il travaille comme assistant de Tazan, un troll qui commerce avec les pirates près de {link:ratchet}Ratchet{/link}. Gamon garde pour son maître des choses que d'autres aimeraient avoir. Il ne remarque pas toujours quand elles disparaissent. Les voleurs du Cleft le savent bien.]=],
		},
		{
			title = "Importance",
