	},
	mentions = {
		{ text = "La Shattered Hand" },
	},
	bonds = {
		{ id = "therzok", name = "Therzok", note = "veut sa clé" },
	},
})

Translate("frFR", "kor-ghan", {
	title = "Kor'ghan",
	subtitle = "Empoisonneur du Cleft",
	found = "Le Cleft of Shadow",
	hint = "Trouvez l'empoisonneur troll dans le Cleft of Shadow.",
	allegiance = "Trolls Darkspear",
	sections = {
		{
			title = "Résumé",
			text = [=[Kor'ghan est un troll {link:darkspear-trolls}Darkspear{/link} qui travaille dans le {link:cleft-of-shadow}Cleft of Shadow{/link}. Il connaît les poisons des scorpides de {link:durotar}Durotar{/link}, et comment faire du venin d'un scorpide son propre remède. C'est aussi un maître sévère des rituels, et ceux qui apprennent auprès de lui doivent faire leurs preuves encore et encore. Ses élèves se plaignent, mais ils vivent.]=],
		},
		{
			title = "Importance",
			text = [=[Kor'ghan est celui que cherchent les jeunes de {link:durotar}Durotar{/link} quand le venin d'un scorpide coule dans leur sang.]=],
		},
		{
			title = "Hauts faits",
			text = [=[• Il prépare un antidote au poison des queues-venin à partir des poches à venin des scorpides eux-mêmes.
• Il sauva le jeune guerrier Rhinag de la piqûre d'une queue-venin.]=],
		},
	},
	mentions = {
		{ text = "Besoin d'un remède" },
		{ text = "Trouver l'antidote" },
	},
})
